use vstd::prelude::*;

verus! {

fn append(a: &Vec<i32>, b: i32) -> (out: Vec<i32>)
    ensures
        // The output is exactly the input elements, followed by `b`
        out@ == a@ + seq![b],
{
    let n: usize = a.len();
    let mut out: Vec<i32> = Vec::with_capacity(n + 1);

    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            // out contains exactly the first i elements of a
            out@ == a@.subrange(0, i as int),
        decreases n - i,
    {
        out.push(a[i]);
        i += 1;
    }

    out.push(b);

    // After pushing b, out is a@ followed by b
    assert(out@ == a@ + seq![b]) by {
        // From loop invariant at exit: out@ == a@.subrange(0, n)
        assert(i == n);
        assert(a@.subrange(0, n as int) == a@);
    };

    out
}

} // verus!

